Fix this TypeScript function and explain the bug briefly. Return the corrected code in one fenced block.

```ts
export function uniqueSorted(values: number[]): number[] {
  return values.sort().filter((value, index, arr) => index === 0 || arr[index - 1] !== value);
}
```

